class Gadget {
    constructor(name, batteryLevel) {
        this.name = name;
        // TODO: Add validation for batteryLevel (0-100). If outside, throw an Error.
        this.batteryLevel = batteryLevel;
    }

    getBatteryStatus() {
        return `${this.name} battery: ${this.batteryLevel}%`;
    }
}

class Smartwatch { // TODO: Inherit from Gadget
    constructor(name, batteryLevel, currentTime) {
        // TODO: Call the parent constructor using super()
        this.currentTime = currentTime;
    }

    displayInfo() {
        // TODO: Return a string combining gadget name, battery status, and current time.
        // Example: "MyWatch battery: 85%, Time: 10:30 AM"
        return `Smartwatch info here`;
    }
}

content.solution_code:
class Gadget {
    constructor(name, batteryLevel) {
        if (batteryLevel < 0 || batteryLevel > 100) {
            throw new Error("Battery level must be between 0 and 100.");
        }
        this.name = name;
        this.batteryLevel = batteryLevel;
    }

    getBatteryStatus() {
        return `${this.name} battery: ${this.batteryLevel}%`;
    }
}

class Smartwatch extends Gadget {
    constructor(name, batteryLevel, currentTime) {
        super(name, batteryLevel);
        this.currentTime = currentTime;
    }

    displayInfo() {
        return `${this.getBatteryStatus()}, Time: ${this.currentTime}`;
    }
}

